/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base GESUMMV kernel. We use scalar temporaries per row to improve
# register reuse and then write the final results back to tmp and y.
@proc
def kernel_gesummv(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    assert n > 0

    for i in seq(0, n):
        # Row-wise accumulated dot products, kept in registers.
        tmp_i: DATA_TYPE
        y_i: DATA_TYPE

        tmp_i = 0.0
        y_i = 0.0

        for j in seq(0, n):
            tmp_i += A[i, j] * x[j]
            y_i += B[i, j] * x[j]

        # Write the final dot-product result to tmp[i] to preserve
        # the original PolyBench semantics, then form y[i].
        tmp[i] = tmp_i
        y[i] = alpha * tmp_i + beta * y[i]

        # The previous line still uses y[i] to preserve the original
        # accumulation pattern (sum over B * x into y[i] first,
        # then apply alpha and beta). To do that while keeping the
        # accumulation in a scalar, we need to store y_i into y[i]
        # before the final combination:
        #
        #   y[i] = y_i
        #   y[i] = alpha * tmp_i + beta * y[i]
        #
        # Implement this explicitly:
        y[i] = y_i
        y[i] = alpha * tmp_i + beta * y[i]


# Scheduling: parallelize the outer loop over rows. The analysis in Exo
# guarantees that different iterations of i are independent, so this
# is safe and lowers to an OpenMP parallel-for on the C side.
kernel_gesummv = parallelize_loop(kernel_gesummv, "i")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_gesummv (/*ctxt=*/NULL, n,
		  (DATA_TYPE*)&alpha,
		  (DATA_TYPE*)&beta,
		  (DATA_TYPE*)POLYBENCH_ARRAY(A),
		  (DATA_TYPE*)POLYBENCH_ARRAY(B),
		  (DATA_TYPE*)POLYBENCH_ARRAY(tmp),
		  (DATA_TYPE*)POLYBENCH_ARRAY(x),
		  (DATA_TYPE*)POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
