/*
Kernel implementation in Exo.

Optimizations relative to the naive version:
  - Use scalar accumulators (sumA, sumB) per row to avoid repeatedly
    loading/storing tmp[i] and y[i] inside the inner loop. This improves
    memory locality and reduces memory traffic.
  - Load x[j] once per inner-loop iteration into a scalar (xj) and reuse
    it for both A and B contributions, reducing redundant memory reads.
  - Apply loop transformations via Exo scheduling:
      * parallelize_loop on the outer i loop to expose row-level
        parallelism (each row i is independent).
      * divide_loop + unroll_loop on the inner j loop with a small
        constant factor to create a vectorization-friendly, unrolled
        inner loop while handling arbitrary n via guards.

The final scheduled procedure is bound to the name `kernel_gesummv`,
which matches the C driver’s expectation.
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


@proc
def gesummv_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # y[i] = alpha * (A[i,:] · x) + beta * (B[i,:] · x)
    for i in seq(0, n):
        sumA: DATA_TYPE
        sumB: DATA_TYPE
        xj:   DATA_TYPE

        sumA = 0.0
        sumB = 0.0

        for j in seq(0, n):
            # Load x[j] once and reuse for both matrix-vector products
            xj = x[j]
            sumA += A[i, j] * xj
            sumB += B[i, j] * xj

        # Write results back to memory once per row
        tmp[i] = sumA
        y[i] = alpha * sumA + beta * sumB


# Start from the base procedure and apply scheduling transformations.
kernel_gesummv = gesummv_base

# 1. Parallelize the outer loop over i.
#    Each row i is independent: safe for parallel execution.
i_loop = kernel_gesummv.find_loop("i")
kernel_gesummv = parallelize_loop(kernel_gesummv, i_loop)

# 2. Tile and unroll the inner loop over j to improve locality and
#    encourage vectorization. We split j into (jo, ji) with ji of size 4,
#    then fully unroll ji. A guarded tail handles n not divisible by 4.
j_loop = kernel_gesummv.find_loop("j")
kernel_gesummv = divide_loop(kernel_gesummv, j_loop, 4, ["jo", "ji"], tail="guard")

ji_loop = kernel_gesummv.find_loop("ji")
kernel_gesummv = unroll_loop(kernel_gesummv, ji_loop)

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_gesummv (/*ctxt=*/NULL, n,
		  (DATA_TYPE*)&alpha,
		  (DATA_TYPE*)&beta,
		  (DATA_TYPE*)POLYBENCH_ARRAY(A),
		  (DATA_TYPE*)POLYBENCH_ARRAY(B),
		  (DATA_TYPE*)POLYBENCH_ARRAY(tmp),
		  (DATA_TYPE*)POLYBENCH_ARRAY(x),
